import csv
import io
import unittest

from app import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_empty_rows_give_empty_text(self) -> None:
        self.assertEqual(export_csv([]), "")

    def test_header_comes_from_first_row_keys_in_order(self) -> None:
        rows = [{"b": 1, "a": 2}, {"b": 3, "a": 4}]
        self.assertEqual(export_csv(rows), "b,a\n1,2\n3,4\n")

    def test_header_only_for_a_single_row(self) -> None:
        self.assertEqual(export_csv([{"id": 7}]), "id\n7\n")

    def test_every_record_is_newline_terminated(self) -> None:
        text = export_csv([{"id": 1}, {"id": 2}])
        self.assertTrue(text.endswith("\n"))
        self.assertEqual(text.splitlines(), ["id", "1", "2"])

    def test_values_are_quoted_when_they_need_it(self) -> None:
        rows = [{"name": "Ada, Lovelace", "note": "line\nbreak"}]
        self.assertEqual(export_csv(rows), 'name,note\n"Ada, Lovelace","line\nbreak"\n')

    def test_missing_keys_become_empty_fields_and_extra_keys_are_skipped(self) -> None:
        rows = [{"a": 1, "b": 2}, {"a": 3, "c": 4}]
        self.assertEqual(export_csv(rows), "a,b\n1,2\n3,\n")

    def test_output_can_be_parsed_back_by_the_csv_module(self) -> None:
        rows = [{"id": 1, "name": "first"}, {"id": 2, "name": "second"}]
        records = list(csv.reader(io.StringIO(export_csv(rows))))
        self.assertEqual(records, [["id", "name"], ["1", "first"], ["2", "second"]])


if __name__ == "__main__":
    unittest.main()

